void multiply(int A[N][N], const int B[N][N]) {
    int C[N][N] = {};

    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            for (size_t k = 0; k < N; ++k) {
                C[i][j] = (C[i][j] + static_cast<ll>(A[i][k]) * B[k][j]) % mod;
